fn update(scene: &mut GameScene<'_>, _time: &FrameTime) {
    let player = scene.object("Player").position();
    for index in 1..=3 {
        let name = format!("Coin {index}");
        let Some(coin) = scene.try_object(&name).map(|coin| coin.position())
        else {
            continue;
        };
        let distance = coin
            .iter()
            .zip(player)
            .map(|(a, b)| (a - b) * (a - b))
            .sum::<f32>()
            .sqrt();
        if distance > 1.0 {
            continue;
        }
        scene.despawn(&name);
        if scene.add_to_counter("coins", 1) == 3 {
            scene.set_hud("Help", |hud| hud.text = "All coins!".into());
        }
    }
}
